# Hypothesis: Particle movement based on type and position parity with nearest neighbor interactions
# Note: This is a best-effort hypothesis. The rule is complex and may not cover all cases.

def hidden_rule_fn(state):
    # State is a list of dicts with 'type', 'x', 'y'
    # Return a list of dicts with 'type', 'x', 'y' for next_state

    def wrap(val, mod=8):
        return val % mod

    def cheb_dist(p1, p2):
        dx = min(abs(p1['x'] - p2['x']), 8 - abs(p1['x'] - p2['x']))
        dy = min(abs(p1['y'] - p2['y']), 8 - abs(p1['y'] - p2['y']))
        return max(dx, dy)

    def splurn(p1, p2):
        return (p1['x'] + p1['y'] + p2['x'] + p2['y']) % 2

    next_state = []

    for i, particle in enumerate(state):
        # Find nearest other particle
        nearest = None
        nearest_dist = float('inf')
        for j, other in enumerate(state):
            if i == j:
                continue
            d = cheb_dist(particle, other)
            if d < nearest_dist:
                nearest_dist = d
                nearest = other

        if nearest is None:
            # Only one particle, don't move
            next_state.append(particle.copy())
            continue

        sp = splurn(particle, nearest)
        p_type = particle['type']

        if p_type == 'BLINX':
            if sp == 0:
                dx, dy = 1, -1
            else:
                dx, dy = -1, 1
        else:  # TORVE
            # TORVE moves only if there's a BLINX in the state
            has_blinx = any(p['type'] == 'BLINX' for p in state)
            if not has_blinx:
                dx, dy = 0, 0
            elif sp == 0:
                # Move towards or away from nearest
                if nearest['type'] == 'BLINX':
                    dx, dy = 1, 1
                else:
                    dx, dy = -1, 1
            else:
                dx, dy = 0, 0

        new_x = wrap(particle['x'] + dx)
        new_y = wrap(particle['y'] + dy)

        next_state.append({'type': p_type, 'x': new_x, 'y': new_y})

    return next_state
